import{_ as t,o,c as a,ag as n}from"./chunks/framework.DoUXNnsN.js";const u=JSON.parse('{"title":"环境变量与PATH","description":"","frontmatter":{"title":"环境变量与PATH","aliases":["环境变量","PATH","Environment Variable","HTTP_PROXY","NO_PROXY","系统变量","用户变量","setx"],"tags":["工具与工程","环境变量","Windows"],"status":"ai-draft","sources":["https://learn.microsoft.com/en-us/dotnet/api/system.environment.setenvironmentvariable","https://learn.microsoft.com/en-us/windows-server/administration/windows-commands/setx","https://curl.se/docs/manpage.html","基于模型知识"],"updated":"2026-10-21T00:00:00.000Z","order":9},"headers":[],"relativePath":"50-工具与工程/环境变量与PATH.md","filePath":"50-工具与工程/环境变量与PATH.md"}'),s={name:"50-工具与工程/环境变量与PATH.md"};function d(c,e,l,i,r,p){return o(),a("div",null,[...e[0]||(e[0]=[n(`<blockquote><p>本篇的命令都在本机（Windows 11，PowerShell 5.1、Git Bash、curl、Python 3.12）实际运行过，输出是真实的。实验中临时创建的环境变量（<code>TOOL2_DEMO</code> 等）已删除。<code>NO_PROXY</code> 对 .NET 程序是否生效等点依据模型知识，未在本机验证。</p></blockquote><blockquote><p>读完你应该能：说清环境变量是什么、进程级/用户级/系统级的区别；看懂并修改 <code>PATH</code>，解释&quot;为什么命令找不到&quot;；理解 <code>HTTP_PROXY</code> 的作用，并能解决&quot;curl 访问本机地址返回 503&quot;这个坑。</p></blockquote><h2 id="一句话定义" tabindex="-1">一句话定义 <a class="header-anchor" href="#一句话定义" aria-label="Permalink to &quot;一句话定义&quot;">​</a></h2><p><strong>环境变量</strong>是操作系统为每个进程保存的一组&quot;名字=值&quot;的键值对，程序启动时可以读取它们，用来获得与运行环境有关的配置（用户名、临时目录、代理地址……）；其中最重要的一个叫 <strong><code>PATH</code></strong>，决定在命令行里敲一个命令名时去哪些目录里找可执行文件。</p><h2 id="先修知识" tabindex="-1">先修知识 <a class="header-anchor" href="#先修知识" aria-label="Permalink to &quot;先修知识&quot;">​</a></h2><ul><li><a href="/Encyclopedia/10-计算机基础/操作系统/操作系统">操作系统</a>：知道&quot;进程&quot;是什么，以及进程可以启动子进程。</li><li><a href="/Encyclopedia/50-工具与工程/命令行与Linux">命令行与Linux</a>：会在终端里敲命令；<a href="/Encyclopedia/50-工具与工程/PowerShell">PowerShell</a>：会用 <code>$env:</code>。</li></ul><h2 id="它解决什么问题" tabindex="-1">它解决什么问题 <a class="header-anchor" href="#它解决什么问题" aria-label="Permalink to &quot;它解决什么问题&quot;">​</a></h2><ol><li><strong>同一份程序，在不同机器上用不同配置，而不用改代码。</strong> 开发机连测试库，生产机连正式库——数据库连接串放在环境变量里，代码里只写&quot;去读 <code>DB_CONN</code>&quot;。<a href="/Encyclopedia/50-工具与工程/Docker/Docker">Docker</a> 容器里传参数也靠它（<code>docker run -e</code>）。</li><li><strong>不用每次写完整路径。</strong> 你敲 <code>python</code> 就能运行，是因为 Python 的安装目录在 <code>PATH</code> 里。</li><li><strong>给一批程序统一设置。</strong> 比如公司上网要走代理，设一次 <code>HTTP_PROXY</code>，curl、pip、npm 等很多工具都会自动遵守。</li><li><strong>不把机密写进代码。</strong> 密码、令牌放环境变量，源码提交进 <a href="/Encyclopedia/50-工具与工程/Git/Git">Git</a> 时不会泄露。</li></ol><h2 id="核心概念" tabindex="-1">核心概念 <a class="header-anchor" href="#核心概念" aria-label="Permalink to &quot;核心概念&quot;">​</a></h2><h3 id="三个-层级-进程级、用户级、系统级" tabindex="-1">三个&quot;层级&quot;：进程级、用户级、系统级 <a class="header-anchor" href="#三个-层级-进程级、用户级、系统级" aria-label="Permalink to &quot;三个&quot;层级&quot;：进程级、用户级、系统级&quot;">​</a></h3><p>这是理解环境变量最关键的一点。</p><table tabindex="0"><thead><tr><th>层级</th><th>保存位置</th><th>谁能看到</th><th>何时生效</th></tr></thead><tbody><tr><td><strong>进程级</strong></td><td>只在进程内存里</td><td>当前进程和它之后启动的<strong>子进程</strong></td><td>立即，进程结束就消失</td></tr><tr><td><strong>用户级</strong></td><td>注册表 <code>HKEY_CURRENT_USER\\Environment</code></td><td>这个 Windows 用户<strong>以后新启动</strong>的程序</td><td>要重新打开程序</td></tr><tr><td><strong>系统级（机器级）</strong></td><td>注册表 <code>HKEY_LOCAL_MACHINE\\...\\Environment</code></td><td>本机所有用户，以后新启动的程序</td><td>要重新打开程序；修改需管理员权限</td></tr></tbody></table><p>一个进程启动时，从父进程<strong>复制一份</strong>环境变量。之后它改自己的副本，不影响父进程，也不影响别的进程。这就像你复印了一份文件再涂改——原件不变。</p><p>于是产生了这些现象（下面&quot;逐步例子&quot;里都实测过）：</p><ul><li>在 PowerShell 里 <code>$env:FOO=&#39;x&#39;</code>，只影响这个 PowerShell 及它启动的程序；</li><li>用 <code>setx</code> 或&quot;系统属性&quot;里改的变量，写进的是<strong>注册表</strong>，<strong>当前已打开的窗口看不到</strong>，要新开窗口（有时需重启 IDE 甚至重新登录）；</li><li>一个进程里 <code>PATH</code> 的最终值，是<strong>系统级 PATH + 用户级 PATH</strong> 合并出来的（实测：系统 26 项 + 用户 9 项 = 进程 35 项）。</li></ul><h3 id="path-命令从哪里找" tabindex="-1">PATH：命令从哪里找 <a class="header-anchor" href="#path-命令从哪里找" aria-label="Permalink to &quot;PATH：命令从哪里找&quot;">​</a></h3><p><code>PATH</code> 是一串目录，Windows 用分号 <code>;</code> 分隔（Linux/macOS 用冒号 <code>:</code>）。敲一个命令（如 <code>python</code>）时，系统先找当前目录/内置命令，然后<strong>按 PATH 从左到右依次</strong>在每个目录里找叫 <code>python.exe</code>（或 <code>.cmd</code>、<code>.bat</code> 等）的文件，<strong>找到第一个就用，后面的忽略</strong>。</p><p>所以：</p><ul><li>命令找不到 → 它所在目录不在 <code>PATH</code> 里；</li><li>装了两个版本的 Python，到底用哪个 → 看哪个目录在 <code>PATH</code> <strong>更靠前</strong>。</li></ul><p>Windows 上能当命令运行的扩展名由环境变量 <code>PATHEXT</code> 决定（<code>.COM;.EXE;.BAT;.CMD;...</code>），所以敲 <code>python</code> 不用写 <code>.exe</code>。</p><h3 id="常见的环境变量" tabindex="-1">常见的环境变量 <a class="header-anchor" href="#常见的环境变量" aria-label="Permalink to &quot;常见的环境变量&quot;">​</a></h3><table tabindex="0"><thead><tr><th>变量</th><th>含义</th><th>例</th></tr></thead><tbody><tr><td><code>PATH</code></td><td>命令搜索路径</td><td>—</td></tr><tr><td><code>TEMP</code> / <code>TMP</code></td><td>临时目录</td><td><code>C:\\Users\\Admin\\AppData\\Local\\Temp</code></td></tr><tr><td><code>USERNAME</code>、<code>USERPROFILE</code></td><td>当前用户名、用户目录</td><td>—</td></tr><tr><td><code>HTTP_PROXY</code>、<code>HTTPS_PROXY</code></td><td>HTTP/HTTPS 请求走的代理</td><td><code>http://127.0.0.1:38888</code></td></tr><tr><td><code>NO_PROXY</code></td><td><strong>不走代理</strong>的地址列表</td><td><code>localhost,127.0.0.1</code></td></tr><tr><td><code>DOTNET_...</code></td><td>.NET 的各种开关</td><td>—</td></tr></tbody></table><h3 id="代理变量-http-proxy-no-proxy" tabindex="-1">代理变量 HTTP_PROXY / NO_PROXY <a class="header-anchor" href="#代理变量-http-proxy-no-proxy" aria-label="Permalink to &quot;代理变量 HTTP_PROXY / NO_PROXY&quot;">​</a></h3><p>**代理（proxy）**是一台&quot;代你上网&quot;的中转服务器：你的程序不直接访问目标网站，而是把请求交给代理，代理再转发。公司上网、访问境外资源常用。</p><p>许多命令行工具（curl、pip、npm、git，Python 的 urllib/requests，.NET 的 HttpClient 等）启动时会读 <code>HTTP_PROXY</code>/<code>HTTPS_PROXY</code>，<strong>之后所有请求都交给代理</strong>。问题来了：访问你<strong>自己电脑上</strong>的服务（<code>localhost</code>）时，也被交给了代理。代理服务器看不到你电脑上的 <code>localhost</code>（它自己的 <code>localhost</code> 是它自己），就会返回错误。<code>NO_PROXY</code> 就是用来把某些地址排除在外的。</p><h3 id="在程序里读取" tabindex="-1">在程序里读取 <a class="header-anchor" href="#在程序里读取" aria-label="Permalink to &quot;在程序里读取&quot;">​</a></h3><p>C# 和 Python 都能读：</p><div class="language-csharp vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">csharp</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">var</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> conn</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> =</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> Environment.</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">GetEnvironmentVariable</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;DB_CONN&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">);   </span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">// 没设置时返回 null</span></span></code></pre></div><div class="language-python vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">python</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">import</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> os</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">conn </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> os.environ.get(</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;DB_CONN&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;默认值&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">)                    </span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># 没设置时用默认值</span></span></code></pre></div><h2 id="逐步例子" tabindex="-1">逐步例子 <a class="header-anchor" href="#逐步例子" aria-label="Permalink to &quot;逐步例子&quot;">​</a></h2><p>以下均在本机实测。</p><h3 id="例-1-进程级变量只在子进程里可见" tabindex="-1">例 1：进程级变量只在子进程里可见 <a class="header-anchor" href="#例-1-进程级变量只在子进程里可见" aria-label="Permalink to &quot;例 1：进程级变量只在子进程里可见&quot;">​</a></h3><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>PS&gt; $env:TOOL2_DEMO = &#39;p&#39;</span></span>
<span class="line"><span>PS&gt; cmd /c &quot;echo cmd child sees: %TOOL2_DEMO%&quot;</span></span>
<span class="line"><span>cmd child sees: p</span></span>
<span class="line"><span>PS&gt; Remove-Item Env:TOOL2_DEMO</span></span>
<span class="line"><span>PS&gt; &quot;after remove: [&quot; + $env:TOOL2_DEMO + &quot;]&quot;</span></span>
<span class="line"><span>after remove: []</span></span></code></pre></div><p>子进程（这里是 cmd）继承了父进程的变量。<code>Remove-Item Env:变量名</code> 删除它。</p><h3 id="例-2-用户级变量写入注册表-但当前窗口看不到" tabindex="-1">例 2：用户级变量写入注册表，但当前窗口看不到 <a class="header-anchor" href="#例-2-用户级变量写入注册表-但当前窗口看不到" aria-label="Permalink to &quot;例 2：用户级变量写入注册表，但当前窗口看不到&quot;">​</a></h3><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>PS&gt; [Environment]::SetEnvironmentVariable(&#39;TOOL2_DEMO&#39;,&#39;u&#39;,&#39;User&#39;)</span></span>
<span class="line"><span>PS&gt; &quot;current session: [&quot; + $env:TOOL2_DEMO + &quot;]&quot;</span></span>
<span class="line"><span>current session: []</span></span>
<span class="line"><span>PS&gt; [Environment]::GetEnvironmentVariable(&#39;TOOL2_DEMO&#39;,&#39;User&#39;)</span></span>
<span class="line"><span>u</span></span>
<span class="line"><span>PS&gt; reg query HKCU\\Environment /v TOOL2_DEMO</span></span>
<span class="line"><span></span></span>
<span class="line"><span>HKEY_CURRENT_USER\\Environment</span></span>
<span class="line"><span>    TOOL2_DEMO    REG_SZ    u</span></span></code></pre></div><p>变量已经写进注册表（<code>reg query</code> 能查到），但<strong>当前会话的 <code>$env:TOOL2_DEMO</code> 仍是空</strong>。新打开的窗口才会看到它。清理：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>PS&gt; [Environment]::SetEnvironmentVariable(&#39;TOOL2_DEMO&#39;,$null,&#39;User&#39;)</span></span></code></pre></div><h3 id="例-3-setx-同样不影响当前窗口" tabindex="-1">例 3：<code>setx</code> 同样不影响当前窗口 <a class="header-anchor" href="#例-3-setx-同样不影响当前窗口" aria-label="Permalink to &quot;例 3：\`setx\` 同样不影响当前窗口&quot;">​</a></h3><p><code>setx</code> 是 Windows 自带的命令，把变量永久写入用户级（加 <code>/M</code> 写系统级，需管理员）：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>PS&gt; setx TOOL2_DEMO2 &quot;viasetx&quot;</span></span>
<span class="line"><span></span></span>
<span class="line"><span>SUCCESS: Specified value was saved.</span></span>
<span class="line"><span>PS&gt; &quot;current session after setx: [&quot; + $env:TOOL2_DEMO2 + &quot;]&quot;</span></span>
<span class="line"><span>current session after setx: []</span></span>
<span class="line"><span>PS&gt; reg delete HKCU\\Environment /v TOOL2_DEMO2 /f</span></span>
<span class="line"><span>The operation completed successfully.</span></span></code></pre></div><p>最后一条是清理实验留下的变量。</p><h3 id="例-4-path-的顺序决定用谁" tabindex="-1">例 4：PATH 的顺序决定用谁 <a class="header-anchor" href="#例-4-path-的顺序决定用谁" aria-label="Permalink to &quot;例 4：PATH 的顺序决定用谁&quot;">​</a></h3><p>建两个目录 <code>pa</code>、<code>pb</code>，各放一个同名脚本 <code>hello2.cmd</code>，内容分别打印 <code>hello from A</code> 和 <code>hello from B</code>。</p><p>把 <code>pb</code> 放在 PATH 前面（<code>$env:Path = &quot;$b;$a;&quot; + $env:Path</code>）：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>PS&gt; cmd /c hello2</span></span>
<span class="line"><span>hello from B</span></span>
<span class="line"><span>PS&gt; Get-Command hello2 -All | ForEach-Object { $_.Source }</span></span>
<span class="line"><span>%TEMP%\\pb\\hello2.cmd</span></span>
<span class="line"><span>%TEMP%\\pa\\hello2.cmd</span></span></code></pre></div><p><code>Get-Command 命令 -All</code> 列出 PATH 里<strong>所有</strong>匹配项，第一个就是会被执行的。把顺序换成 <code>pa</code> 在前，再运行就输出 <code>hello from A</code>。这就是&quot;装了两个 Python 却跑了错的那个&quot;的原理。</p><h3 id="例-5-path-的组成" tabindex="-1">例 5：PATH 的组成 <a class="header-anchor" href="#例-5-path-的组成" aria-label="Permalink to &quot;例 5：PATH 的组成&quot;">​</a></h3><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>PS&gt; ($env:Path -split &#39;;&#39; | Where-Object { $_ }).Count</span></span>
<span class="line"><span>35</span></span>
<span class="line"><span>PS&gt; ([Environment]::GetEnvironmentVariable(&#39;Path&#39;,&#39;User&#39;) -split &#39;;&#39; | Where-Object { $_ }).Count</span></span>
<span class="line"><span>9</span></span>
<span class="line"><span>PS&gt; ([Environment]::GetEnvironmentVariable(&#39;Path&#39;,&#39;Machine&#39;) -split &#39;;&#39; | Where-Object { $_ }).Count</span></span>
<span class="line"><span>26</span></span></code></pre></div><p>35 = 9 + 26。数字因机器而异，规律不变：<strong>进程 PATH = 系统 PATH + 用户 PATH</strong>。</p><h3 id="例-6-http-proxy-让访问本机的-curl-返回-503" tabindex="-1">例 6：HTTP_PROXY 让访问本机的 curl 返回 503 <a class="header-anchor" href="#例-6-http-proxy-让访问本机的-curl-返回-503" aria-label="Permalink to &quot;例 6：HTTP_PROXY 让访问本机的 curl 返回 503&quot;">​</a></h3><p>本机设置了 <code>HTTP_PROXY=HTTPS_PROXY=http://127.0.0.1:38888</code>（代理软件监听在本机 38888 端口）。起一个只监听 8000 端口的小服务（用 Python 标准库，见 <a href="/Encyclopedia/50-工具与工程/Docker/Dockerfile">Dockerfile</a> 里的 <code>app.py</code>），然后用 Git Bash 里的 curl 访问，只打印 HTTP 状态码：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>$ curl -s -o /dev/null -w &quot;%{http_code}\\n&quot; http://localhost:8000/</span></span>
<span class="line"><span>503</span></span>
<span class="line"><span>$ curl -s -o /dev/null -w &quot;%{http_code}\\n&quot; --noproxy &#39;*&#39; http://localhost:8000/</span></span>
<span class="line"><span>200</span></span>
<span class="line"><span>$ NO_PROXY=localhost,127.0.0.1 curl -s -o /dev/null -w &quot;%{http_code}\\n&quot; http://localhost:8000/</span></span>
<span class="line"><span>200</span></span>
<span class="line"><span>$ curl -s -o /dev/null -w &quot;%{http_code}\\n&quot; http://127.0.0.1:8000/</span></span>
<span class="line"><span>503</span></span>
<span class="line"><span>$ env -u HTTP_PROXY -u HTTPS_PROXY curl -s -o /dev/null -w &quot;%{http_code}\\n&quot; http://localhost:8000/</span></span>
<span class="line"><span>200</span></span></code></pre></div><p>解读：</p><ol><li>默认 → <strong>503</strong>：curl 读到 <code>HTTP_PROXY</code>，把 <code>localhost:8000</code> 的请求发给了 38888 的代理，代理转发不了，返回 503。<strong>服务本身没问题</strong>——小服务的日志里甚至没有这次请求。</li><li><code>--noproxy &#39;*&#39;</code>（curl 的参数，<code>*</code> 表示所有主机都不走代理）→ 200。</li><li>设置 <code>NO_PROXY</code> → 200。</li><li>用 <code>127.0.0.1</code> 也一样 503：不是 <code>localhost</code> 这个名字的问题，而是<strong>所有请求</strong>都走了代理。</li><li>取消代理变量 → 200。</li></ol><p>Python 的 <code>urllib</code> 同样中招（本机实测）：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>&gt;&gt;&gt; urllib.request.urlopen(&#39;http://localhost:8000/&#39;)</span></span>
<span class="line"><span>HTTP Error 503: Service Unavailable</span></span>
<span class="line"><span>&gt;&gt;&gt; urllib.request.getproxies()</span></span>
<span class="line"><span>{&#39;https&#39;: &#39;http://127.0.0.1:38888&#39;, &#39;http&#39;: &#39;http://127.0.0.1:38888&#39;}</span></span></code></pre></div><p><strong>这是一类很常见的&quot;假故障&quot;</strong>：服务明明启动了，curl/脚本却报 503、502 或超时。排查方法：先 <code>echo $HTTP_PROXY</code>（PowerShell：<code>$env:HTTP_PROXY</code>）看有没有设代理。</p><h2 id="动手实验" tabindex="-1">动手实验 <a class="header-anchor" href="#动手实验" aria-label="Permalink to &quot;动手实验&quot;">​</a></h2><ol><li>查看当前变量：PowerShell 里 <code>Get-ChildItem Env:</code>（全部）、<code>$env:TEMP</code>、<code>$env:Path -split &#39;;&#39;</code>；cmd 里 <code>set</code>、<code>echo %TEMP%</code>；Git Bash 里 <code>env</code>、<code>echo $HOME</code>。</li><li>重做例 1 ~ 3，<strong>实验完务必按文中的清理命令删除</strong>临时变量。</li><li>图形界面操作：开始菜单搜&quot;编辑系统环境变量&quot; → &quot;环境变量&quot;按钮。上半部分是用户变量，下半部分是系统变量。新建一个 <code>MY_NAME</code>，确定后<strong>新开</strong>一个 PowerShell 执行 <code>$env:MY_NAME</code>，看到值；旧窗口里则没有。再删除它。</li><li>重做例 4，体会 PATH 顺序。动手前注意：只改<strong>当前会话</strong>的 <code>$env:Path</code>，不要修改永久的 PATH。</li><li>如果你的电脑也设了代理，起 <code>python -m http.server 8000</code>，用 <code>curl http://localhost:8000/</code> 和加 <code>--noproxy &#39;*&#39;</code> 各试一次。没设代理就用 <code>$env:HTTP_PROXY=&#39;http://127.0.0.1:1&#39;</code> 临时模拟（只影响当前会话），再试一次，会看到连接失败。做完 <code>Remove-Item Env:HTTP_PROXY</code>。</li><li>写一个读 <code>GREETING</code> 的小程序（见 <a href="/Encyclopedia/50-工具与工程/Docker/Dockerfile">Dockerfile</a> 里的 .NET 例子），分别在设置和不设置时运行，观察输出（本机实测：不设时输出 <code>Hello, ...</code>，设 <code>GREETING=Hi</code> 时输出 <code>Hi, ...</code>）。</li></ol><h2 id="常见坑与排查" tabindex="-1">常见坑与排查 <a class="header-anchor" href="#常见坑与排查" aria-label="Permalink to &quot;常见坑与排查&quot;">​</a></h2><table tabindex="0"><thead><tr><th>现象</th><th>原因与办法</th></tr></thead><tbody><tr><td>改了环境变量，程序里读到的还是旧的</td><td>程序/IDE 是在修改之前启动的，变量是启动时复制的。<strong>关闭重开</strong>程序，必要时重开 Visual Studio / 终端</td></tr><tr><td>安装软件后命令找不到</td><td>新装的程序改了 PATH，但当前终端是旧的。新开终端</td></tr><tr><td><code>curl</code>/脚本访问 <code>localhost</code> 返回 503、502 或超时</td><td>设了 <code>HTTP_PROXY</code>。用 <code>--noproxy &#39;*&#39;</code>，或设 <code>NO_PROXY=localhost,127.0.0.1</code>，或临时取消代理变量</td></tr><tr><td>某些程序认大写 <code>HTTP_PROXY</code>，有的认小写 <code>http_proxy</code></td><td>不同工具约定不同，两种都设最稳妥（Windows 变量名本身不区分大小写，Linux 区分）</td></tr><tr><td>命令 <code>python</code> 打开了应用商店</td><td>Windows 自带的&quot;应用执行别名&quot;占了位置；在&quot;管理应用执行别名&quot;里关掉，或把真正的 Python 目录放在 PATH 更前面</td></tr><tr><td>PATH 太长被截断/加不进去</td><td>老式界面对单个变量有长度限制；清理无用项，或改用工具/短路径</td></tr><tr><td>用 <code>setx</code> 改 PATH 把 PATH 搞坏了</td><td>微软文档：<code>setx</code> 赋值内容超过 <strong>1024 字符会被截断</strong>，截断后的内容直接写入目标变量，会丢失原有数据；它还会把变量里的 <code>%引用%</code> 展开成固定值。常见的 <code>setx PATH &quot;%PATH%;新目录&quot;</code> 恰好会写入&quot;系统+用户合并后&quot;的整个 PATH，容易出事。<strong>不要用 setx 改 PATH</strong>，用图形界面编辑</td></tr><tr><td>密码放环境变量就安全了</td><td>并不：同一用户下的其它进程、进程列表、日志可能暴露它。它只是比写进源码强，机密应由专门的密钥管理处理</td></tr><tr><td>Docker 里的程序读不到变量</td><td>容器有自己的环境变量，宿主机的不会自动带进去，要 <code>-e</code> 或 Compose 的 <code>environment:</code>，见 <a href="/Encyclopedia/50-工具与工程/Docker/Docker镜像与容器">Docker镜像与容器</a></td></tr><tr><td>打包脚本里的路径含 <code>%USERPROFILE%</code> 不展开</td><td>cmd 才展开 <code>%VAR%</code>；PowerShell 用 <code>$env:VAR</code>；Bash 用 <code>$VAR</code>。在 .NET 里可用 <code>Environment.ExpandEnvironmentVariables</code></td></tr></tbody></table><h2 id="练习题与答案" tabindex="-1">练习题与答案 <a class="header-anchor" href="#练习题与答案" aria-label="Permalink to &quot;练习题与答案&quot;">​</a></h2><p><strong>1.</strong> 在 PowerShell 里执行 <code>$env:APP_MODE=&#39;test&#39;</code> 后，能否在另一个已打开的 PowerShell 窗口读到？</p><p>答：不能。这是进程级变量，只存在于当前进程及其以后启动的子进程。</p><p><strong>2.</strong> 用 <code>setx X 1</code> 之后，当前窗口里 <code>echo %X%</code> 能看到吗？</p><p>答：看不到。<code>setx</code> 写的是注册表，只对<strong>之后新启动</strong>的进程生效（本篇例 3 实测）。</p><p><strong>3.</strong> 系统里装了 Python 3.9 和 3.12，输入 <code>python</code> 却启动了 3.9，怎么办？</p><p>答：用 <code>Get-Command python -All</code> 看 PATH 里各匹配项的顺序，把 3.12 的目录挪到 3.9 前面（或删除不需要的）。更好的做法是为每个项目用虚拟环境，见 <a href="/Encyclopedia/20-编程语言/Python/Python环境搭建">Python环境搭建</a>。</p><p><strong>4.</strong> 解释命令 <code>curl --noproxy &#39;*&#39; http://localhost:8000/</code>。</p><p>答：向本机 8000 端口发请求，<code>--noproxy &#39;*&#39;</code> 让 curl 对所有地址都不使用代理，即使环境变量里设了 <code>HTTP_PROXY</code>。</p><p><strong>5.</strong> <code>NO_PROXY=localhost,127.0.0.1</code> 里的逗号分隔列表有什么用？</p><p>答：列出的主机访问时不经过代理，直接连接。解决了&quot;本机服务被代理拦截&quot;。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>环境变量是进程启动时从父进程<strong>复制</strong>的键值对；分进程级、用户级（HKCU）、系统级（HKLM），后两者只对<strong>新启动</strong>的程序生效。</li><li><code>PATH</code> 按顺序从左到右查找命令，先找到先用；进程 PATH = 系统 PATH + 用户 PATH。</li><li>代理变量 <code>HTTP_PROXY</code>/<code>HTTPS_PROXY</code> 会让很多工具的请求包括 <code>localhost</code> 都走代理，导致&quot;本机服务 curl 返回 503&quot;；用 <code>--noproxy &#39;*&#39;</code> 或 <code>NO_PROXY</code> 解决。</li><li>程序里用 <code>Environment.GetEnvironmentVariable</code>（C#）或 <code>os.environ</code>（Python）读取；机密不要写进源码。</li></ul><h2 id="相关词条" tabindex="-1">相关词条 <a class="header-anchor" href="#相关词条" aria-label="Permalink to &quot;相关词条&quot;">​</a></h2><p><a href="/Encyclopedia/50-工具与工程/PowerShell">PowerShell</a>、<a href="/Encyclopedia/50-工具与工程/命令行与Linux">命令行与Linux</a>、<a href="/Encyclopedia/50-工具与工程/Docker/Docker">Docker</a>、<a href="/Encyclopedia/50-工具与工程/Docker/Docker镜像与容器">Docker镜像与容器</a>、<a href="/Encyclopedia/50-工具与工程/Docker/Dockerfile">Dockerfile</a>、<a href="/Encyclopedia/10-计算机基础/操作系统/操作系统">操作系统</a>、<a href="/Encyclopedia/30-.NET生态/配置与日志">配置与日志</a>、<a href="/Encyclopedia/10-计算机基础/计算机网络/HTTP">HTTP</a></p><h2 id="延伸阅读" tabindex="-1">延伸阅读 <a class="header-anchor" href="#延伸阅读" aria-label="Permalink to &quot;延伸阅读&quot;">​</a></h2><ul><li>.NET <code>Environment.SetEnvironmentVariable</code>：<a href="https://learn.microsoft.com/en-us/dotnet/api/system.environment.setenvironmentvariable" target="_blank" rel="noreferrer">https://learn.microsoft.com/en-us/dotnet/api/system.environment.setenvironmentvariable</a></li><li><code>setx</code> 命令参考：<a href="https://learn.microsoft.com/en-us/windows-server/administration/windows-commands/setx" target="_blank" rel="noreferrer">https://learn.microsoft.com/en-us/windows-server/administration/windows-commands/setx</a></li><li>curl 手册（<code>--noproxy</code>、代理环境变量）：<a href="https://curl.se/docs/manpage.html" target="_blank" rel="noreferrer">https://curl.se/docs/manpage.html</a></li></ul>`,79)])])}const g=t(s,[["render",d]]);export{u as __pageData,g as default};
